css:
.pv{position:relative;--fg:#171717;--fg2:#737373;--bg:#fff;--muted:#F5F5F5;--line:#E5E5E5;--inv:#171717;--invfg:#fff;--sh:0 4px 12px rgba(16,24,40,.10),0 1px 3px rgba(16,24,40,.06);
 --ok:#1B7542;--ok-i:#348D57;--ok-bg:#E8F5EC;--ok-bd:#93CFA6;--warn:#8A5300;--warn-i:#A56A21;--warn-bg:#FFF3DC;--warn-bd:#E3B87A;
 --err:#B42318;--err-i:#D23C2E;--err-bg:#FDECEC;--err-bd:#FFA19C;--info:#1F4FB8;--info-i:#3468D7;--info-bg:#E7EFFD;--info-bd:#93B9FF;
 color:var(--fg);font:14px/20px Inter,system-ui,sans-serif}
.pv[data-theme=dark]{--fg:#F5F5F5;--fg2:#A3A3A3;--bg:#0A0A0A;--muted:#171717;--line:#262626;--inv:#F5F5F5;--invfg:#0A0A0A;--sh:0 4px 12px rgba(0,0,0,.5);
 --ok:#93CFA6;--ok-i:#6FBB89;--ok-bg:#013519;--ok-bd:#1B7542;--warn:#E3B87A;--warn-i:#D19D59;--warn-bg:#3F2300;--warn-bd:#8A5300;
 --err:#FFA19C;--err-i:#FC7970;--err-bg:#580100;--err-bd:#B42318;--info:#93B9FF;--info-i:#6C9EFE;--info-bg:#051F5C;--info-bd:#1F4FB8}
.card.m{padding:14px}
.i{flex:none;display:block}
.ok{--t:var(--ok);--ti:var(--ok-i);--tbg:var(--ok-bg);--tbd:var(--ok-bd)}
.warn{--t:var(--warn);--ti:var(--warn-i);--tbg:var(--warn-bg);--tbd:var(--warn-bd)}
.err{--t:var(--err);--ti:var(--err-i);--tbg:var(--err-bg);--tbd:var(--err-bd)}
.info{--t:var(--info);--ti:var(--info-i);--tbg:var(--info-bg);--tbd:var(--info-bd)}
.tz{position:absolute;z-index:5;display:flex;flex-direction:column;gap:8px;width:400px;right:24px;top:80px}
.pv[data-D4=b] .tz:not(.m){top:auto;bottom:24px}
.pv[data-D4=c] .tz:not(.m){right:auto;left:calc(50% + 120px);transform:translateX(-50%)}
.tz.m{left:12px;right:12px;width:auto;top:52px}
.pv[data-D8=b] .tz.m{top:auto;bottom:76px}
.ts{position:relative;display:flex;gap:12px;align-items:flex-start;padding:12px;border-radius:12px;box-shadow:var(--sh);overflow:hidden;
 background:var(--bg);color:var(--fg);border:1px solid var(--line)}
.ts .ib{color:var(--ti);display:grid;place-items:center}
.ts .tx{flex:1;min-width:0;padding-top:1px}
.ts .tt{font-weight:600;font-size:14px;line-height:20px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}
.ts .ds{color:var(--fg2);font-size:12px;line-height:18px;margin-top:2px}
.ac{display:flex;gap:12px;margin-top:6px}
.lk{border:0;background:none;padding:0;font:600 12px/18px Inter;position:relative;color:var(--fg2);cursor:pointer}
.lk.pri{color:var(--fg)}
.cl{position:relative;border:0;background:none;padding:2px;color:var(--fg2);cursor:pointer;display:grid;place-items:center;margin:-2px -2px 0 0;opacity:.8}
.tm{position:absolute;left:0;bottom:0;height:4px;width:62%;background:var(--ti);display:none}
.pv[data-D6=b] .tm{display:block}
.pv[data-D1=a] .ts{background:var(--inv);color:var(--invfg);border-color:transparent}
.pv[data-D1=a] .ts .ds,.pv[data-D1=a] .ts .lk,.pv[data-D1=a] .ts .cl{color:color-mix(in srgb,var(--invfg) 72%,transparent)}
.pv[data-D1=a] .ts .lk.pri{color:var(--invfg);text-decoration:underline}
.pv[data-D1=a] .ts .ib{color:color-mix(in srgb,var(--ti) 55%,var(--invfg))}
.pv[data-D1=a] .ts.err{background:var(--err-i);color:#fff}
.pv[data-D1=a] .ts.err .ib,.pv[data-D1=a] .ts.err .ds,.pv[data-D1=a] .ts.err .lk,.pv[data-D1=a] .ts.err .cl{color:#fff}
.pv[data-D1=c] .ts{background:var(--tbg);border-color:var(--tbd);box-shadow:0 2px 6px rgba(16,24,40,.06)}
.pv[data-D1=c] .ts .tt{color:var(--t)}
.cl::after,.lk::after{content:"";position:absolute;left:50%;top:50%;width:24px;height:24px;min-width:100%;transform:translate(-50%,-50%)}
.pv[data-platform=mobile] .cl::after,.pv[data-platform=mobile] .lk::after{width:44px;height:44px}
.pv[data-platform=mobile] .ts .ac{gap:24px}
.pv[data-platform=mobile] .al .bt{height:36px;position:relative}
.pv[data-platform=mobile] .al .bt::after{content:"";position:absolute;inset:-4px 0}
.nt{--t:var(--fg);--ti:var(--fg2);--tbg:var(--muted);--tbd:var(--line)}
.av{width:32px;height:32px;border-radius:999px;background:#E7EFFD;color:#1F4FB8;font:600 12px/32px Inter;text-align:center;position:relative;flex:none;margin:-6px 0 -6px -2px}
.pv[data-theme=dark] .av{background:#051F5C;color:#93B9FF}
.av .on{position:absolute;right:-1px;bottom:-1px;width:10px;height:10px;border-radius:999px;background:#348D57;border:2px solid var(--bg)}
.pg{display:flex;align-items:center;gap:10px;margin-top:8px}
.pb{flex:1;height:6px;border-radius:999px;background:var(--muted);overflow:hidden}
.pb i{display:block;height:100%;background:var(--info-i);border-radius:999px}
.pg span{font:500 12px/18px Inter;color:var(--fg2);font-variant-numeric:tabular-nums;min-width:32px;text-align:right}
.pg+.ds{font-size:12px;margin-top:2px}
.al{display:flex;gap:12px;align-items:flex-start;padding:12px;border-radius:10px;border:1px solid var(--tbd);background:var(--tbg)}
.al .ib{color:var(--ti);display:grid;place-items:center}
.al .tx{flex:1;min-width:0;padding-top:1px}
.al .tt{font-weight:600;color:var(--t)}
.al .ds{font-size:12px;line-height:18px;color:var(--fg);margin-top:2px}
.al .ac{margin:0;align-self:center;flex:none}
.bt{height:32px;padding:0 12px;border-radius:8px;border:1px solid var(--line);background:var(--bg);color:var(--fg);font:600 13px Inter;cursor:pointer}
.al .cl{align-self:flex-start}
.pv[data-D5=a] .al{flex-wrap:wrap}
.pv[data-D5=a] .al .ac{order:3;flex-basis:100%;padding-left:32px;margin-top:8px}
.pv[data-D5=a] .al .cl{order:2}
.al.stack{flex-wrap:wrap}
.al.stack .ac{order:3;flex-basis:100%;padding-left:32px;margin-top:8px}
.pv[data-D3=a] .al.stack .ac{padding-left:44px}
.pv[data-D2=b] .al{background:var(--bg);border-color:var(--line);border-left:4px solid var(--ti);padding-left:12px}
.pv[data-D2=b] .al .tt{color:var(--fg)}
.pv[data-D2=c] .al{background:var(--bg);border-color:var(--t)}
.pv[data-D2=c] .al .tt{color:var(--fg)}
.pv[data-D3=a] .ib{width:32px;height:32px;border-radius:999px;background:var(--tbg);margin:-6px 0 -6px -2px;box-shadow:0 0 0 4px color-mix(in srgb,var(--tbg) 45%,transparent)}
.pv[data-D3=a][data-D1=a] .ts .ib{background:color-mix(in srgb,var(--invfg) 14%,transparent);box-shadow:none}
.pv[data-D3=a] .ib .i{width:20px;height:20px}
.bn .bt{height:28px;border-color:var(--warn-bd);background:transparent;color:var(--warn)}
.pv[data-platform=mobile] .bn{padding:8px 16px}
.pv[data-platform=mobile] .grid2{grid-template-columns:1fr}
.tz.static{position:static;width:100%;transform:none}

cssScreen:
.mono{font-family:'JetBrains Mono',ui-monospace,monospace;font-size:13px}
.pad{padding:16px 24px 24px;display:flex;flex-direction:column;gap:16px}
.mpad{padding:12px 16px;display:flex;flex-direction:column;gap:12px}
.tb{border:1px solid var(--line);border-radius:12px;overflow:hidden}
table{width:100%;border-collapse:collapse}
td,th{padding:11px 16px;border-bottom:1px solid var(--line);text-align:left;font-size:13px}
tr:last-child td{border-bottom:0}
th{color:var(--fg2);font-weight:500;background:var(--muted)}
.chip{display:inline-block;font:500 12px/18px Inter;padding:2px 8px;border-radius:999px;background:var(--muted);color:var(--fg)}
.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.span2{grid-column:span 2}
.card{border:1px solid var(--line);border-radius:12px;padding:16px;display:flex;flex-direction:column;gap:12px}
.card .h{font:600 15px/22px Inter}
dl{display:grid;grid-template-columns:110px 1fr;gap:6px 12px;margin:0;font-size:13px}
dt{color:var(--fg2)}
dd{margin:0}
.mrow{padding:12px 16px;border-bottom:1px solid var(--line);display:grid;grid-template-columns:1fr auto;gap:2px 8px}
.mrow .b{font-weight:600}
.mrow .sub{color:var(--fg2);font-size:13px;grid-column:1}
.mrow .chip{grid-row:1/span 2;grid-column:2;align-self:center}
.cta{height:52px;border:0;border-radius:999px;background:var(--inv);color:var(--invfg);font:600 16px Inter;margin-top:8px}
.bn{display:flex;align-items:center;gap:10px;padding:8px 24px;background:var(--warn-bg);color:var(--warn);border-bottom:1px solid var(--warn-bd);font-size:13px}
.bn span{flex:1}
.bn b{font-weight:600}
